fn flip(a: &mut Vec<i32>, num: usize) {
    // Reverse the inclusive prefix [0..=num] in-place.
    // Since we assume `num < a.len()`, this is always valid.
    let mut left = 0;
    let mut right = num;
    while left < right {
        a.swap(left, right);
        left += 1;
        right -= 1;
    }
}

